-- 配管系統図のサンプルデータ（仮想空港給油施設・第1版）
-- 先に supabase/piping_diagram.sql を実行してから、このファイルを SQL Editor で実行してください。
-- 何度実行しても同じ内容に入れ替わります（第1版の機器・配管・区画を削除して入れ直す）。
-- このファイルは tools/piping-diagram/generate-seed.cjs で src/lib/piping/facility.ts から生成しています。

begin;

  on conflict (id) do update set name = excluded.name, width = excluded.width, height = excluded.height, meters_per_px = excluded.meters_per_px;

update piping_diagram_versions set status = 'retired' where facility_id = 'virtual-airport' and id <> 'virtual-airport-v1' and status = 'active';
  on conflict (id) do update set status = 'active', note = excluded.note;

delete from piping_diagram_pipes where version_id = 'virtual-airport-v1';
delete from piping_diagram_nodes where version_id = 'virtual-airport-v1';
delete from piping_diagram_areas where version_id = 'virtual-airport-v1';









commit;

-- 機器 553 件・配管 638 件・区画 8 件
